import re

try:
    from taf.analyzer.syslog import SysLogReader
except ImportError:
    pass


class Reader(object):
    def __enter__(self):
        raise NotImplementedError()

    def __exit__(self, exc_type, exc_val, exc_tb):
        raise NotImplementedError()

    @property
    def log_entries(self):
        raise NotImplementedError()


class FileReader(Reader):
    def __init__(self, log):
        self._log = log
        self._fobj = None

    def __enter__(self):
        self._fobj = open(self._log, "rb")
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self._fobj:
            self._fobj.close()
            self._fobj = None

    @property
    def log_entries(self):
        return SysLogReader(file_obj_iterator=(self._fobj, ))


class AASyslogLineParser(object):
    class Entry(object):
        def __init__(self, node):
            self._node = node
            self._timestamp = node['timestamp']

        @property
        def syslog_msg(self):
            return self._node

        @property
        def timestamp(self):
            return self._timestamp

    def parse_line(self, syslog_string):
        syslog_string = str(syslog_string)
        node_name = self._match_regex(
            r"(?:\] )?(?P<node_seq_nr>[a-f\d]{2}) (?P<node_name>.*?)-(?P<domain_number>.*?)-(?P<ee_name>\S*) <"
            r"(?P<EU_Id>\d+[A-Z]*)",
            syslog_string)
        timestamp = re.search(r"<([0-9]*-[0-9]*-[0-9]*T[0-9]*:[0-9]*:[0-9]*.[0-9]*Z)>",
                              syslog_string)
        if timestamp:
            timestamp = timestamp.groups(1)

        node_name.update({'raw_string': syslog_string})
        node_name.update({'timestamp': timestamp})
        return AASyslogLineParser.Entry(node_name)

    def _match_regex(self, line, syslog_string):
        syslog_msg = re.search(line, syslog_string)
        if syslog_msg:
            syslog_msg = syslog_msg.groupdict()
        else:
            # write a generic approach to read the keys and assign to None
            syslog_msg = {'node_seq_nr': None, 'node_name': None, 'domain_number': None, 'ee_name': None}
        return syslog_msg


class WAFileReader(FileReader):
    """ a Workaround class for the SysLogReader blocking"""

    def __init__(self, log):
        super(WAFileReader, self).__init__(log)
        self._parser = AASyslogLineParser()


    @property
    def log_entries(self):
        return self

    def __iter__(self):
        for line in self._fobj:
            real_lines = self._try_to_get_lines(line)
            for real_line in real_lines:
                yield self._parser.parse_line(real_line)

    def _try_to_get_lines(self, content):
        pattern = r"([a-fA-F\d]{2} \w+-\w+-\w+ <)(.*?((?=[a-fA-F\d]{2} \w+-\w+-\w+ <)|(?=\r\n)))"
        content = str(content) + '\r\n'
        lines = re.findall(pattern, content)
        if len(lines) > 1:
            return [line[0] + line[1] for line in lines]
        return [content]
